CREATE DATABASE IF NOT EXISTS `al_najat_records_db` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `al_najat_records_db`;
CREATE TABLE `records_archive_years` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`application_year` YEAR NOT NULL,`exam_year` INT NULL,`archive_status` ENUM('ACTIVE','ARCHIVING','ARCHIVED','REOPENED','RETIRED') NOT NULL DEFAULT 'ACTIVE',`archived_at` DATETIME NULL,`reopened_at` DATETIME NULL,`created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY (`id`),UNIQUE KEY `uq_archive_year` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_schools` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`school_code` VARCHAR(50) NOT NULL,`school_name` VARCHAR(255) NOT NULL,`school_type` ENUM('School','Madrasa','School & Madrasa','College','Other') NOT NULL,`head_name` VARCHAR(150) NULL,`mobile` VARCHAR(20) NULL,`email` VARCHAR(150) NULL,`address` TEXT NULL,`village` VARCHAR(150) NULL,`post_office` VARCHAR(150) NULL,`district` VARCHAR(100) NULL,`state` VARCHAR(100) NULL,`pincode` VARCHAR(20) NULL,`status` ENUM('Pending','Approved','Rejected','Inactive') NOT NULL,`remarks` TEXT NULL,`created_by` INT NULL,`approved_by` INT NULL,`approved_at` DATETIME NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_school_year_code` (`application_year`,`school_code`),CONSTRAINT `fk_records_schools_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_centres` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`centre_id` VARCHAR(20) NOT NULL,`centre_code` VARCHAR(30) NOT NULL,`centre_name` VARCHAR(200) NOT NULL,`centre_type` ENUM('School','Madrasa','College','Institution','Other') NOT NULL,`head_name` VARCHAR(150) NULL,`mobile` VARCHAR(20) NULL,`email` VARCHAR(120) NULL,`address` TEXT NULL,`village` VARCHAR(150) NULL,`post_office` VARCHAR(150) NULL,`district` VARCHAR(100) NULL,`state` VARCHAR(100) NOT NULL DEFAULT 'Assam',`pincode` VARCHAR(20) NULL,`capacity` INT NULL,`status` ENUM('Pending','Approved','Rejected','Inactive','Suspended') NOT NULL,`remarks` TEXT NULL,`created_by` INT NULL,`approved_by` INT NULL,`approved_at` DATETIME NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_centre_year_id` (`application_year`,`centre_id`),UNIQUE KEY `uq_centre_year_code` (`application_year`,`centre_code`),CONSTRAINT `fk_records_centres_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_seat_plan_shifts` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`shift_no` INT NOT NULL,`shift_name` VARCHAR(100) NOT NULL,`is_active` TINYINT(1) NOT NULL DEFAULT 1,`layout` ENUM('TWO_SIDE','SINGLE_LINE') NOT NULL DEFAULT 'TWO_SIDE',`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_shift_year_no` (`application_year`,`shift_no`),CONSTRAINT `fk_records_shifts_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_exam_settings` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`exam_name` VARCHAR(255) NULL,`exam_year` INT NULL,`exam_date` DATE NULL,`reporting_time` TIME NULL,`exam_start_time` TIME NULL,`exam_end_time` TIME NULL,`result_publish_date` DATE NULL,`certificate_publish_date` DATE NULL,`application_start_date` DATE NULL,`application_end_date` DATE NULL,`exam_centre` VARCHAR(255) NULL,`controller_name` VARCHAR(255) NULL,`status` ENUM('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),CONSTRAINT `fk_records_exam_settings_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_exam_shifts` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`exam_setting_id` INT NOT NULL,`shift_id` INT NOT NULL,`reporting_time` TIME NULL,`exam_start_time` TIME NULL,`exam_end_time` TIME NULL,`is_active` TINYINT(1) NOT NULL DEFAULT 1,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_exam_shift` (`application_year`,`exam_setting_id`,`shift_id`),CONSTRAINT `fk_records_exam_shifts_settings` FOREIGN KEY (`application_year`,`exam_setting_id`) REFERENCES `records_exam_settings` (`application_year`,`id`),CONSTRAINT `fk_records_exam_shifts_shift` FOREIGN KEY (`application_year`,`shift_id`) REFERENCES `records_seat_plan_shifts` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_exam_shift_sections` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`exam_shift_id` INT NOT NULL,`section` CHAR(1) NOT NULL,`created_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),CONSTRAINT `fk_records_exam_shift_sections_shift` FOREIGN KEY (`application_year`,`exam_shift_id`) REFERENCES `records_exam_shifts` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_seat_plan_rooms` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`shift_id` INT NOT NULL,`room_no` INT NOT NULL,`is_active` TINYINT(1) NOT NULL DEFAULT 1,`seat_system` ENUM('FULL','CORNER_TO_CORNER') NOT NULL DEFAULT 'FULL',`left_gender_lock` VARCHAR(20) NULL,`right_gender_lock` VARCHAR(20) NULL,`left_section_lock` VARCHAR(20) NULL,`right_section_lock` VARCHAR(20) NULL,`universal_gender_lock` VARCHAR(20) NULL,`universal_section_lock` VARCHAR(20) NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_room_year_shift_room` (`application_year`,`shift_id`,`room_no`),CONSTRAINT `fk_records_rooms_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`),CONSTRAINT `fk_records_rooms_shift` FOREIGN KEY (`application_year`,`shift_id`) REFERENCES `records_seat_plan_shifts` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_seat_plan_seats` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`shift_id` INT NOT NULL,`room_id` INT NOT NULL,`row_no` INT NULL,`seat_no` INT NOT NULL,`position` ENUM('LEFT','RIGHT','SINGLE') NOT NULL,`section` CHAR(1) NULL,`gender` ENUM('Male','Female','Any') NOT NULL DEFAULT 'Any',`is_active` TINYINT(1) NOT NULL DEFAULT 1,`is_locked` TINYINT(1) NOT NULL DEFAULT 0,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_seat_year_room_seat` (`application_year`,`room_id`,`seat_no`),CONSTRAINT `fk_records_seats_shift` FOREIGN KEY (`application_year`,`shift_id`) REFERENCES `records_seat_plan_shifts` (`application_year`,`id`),CONSTRAINT `fk_records_seats_room` FOREIGN KEY (`application_year`,`room_id`) REFERENCES `records_seat_plan_rooms` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_applications` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`registration_no` VARCHAR(20) NOT NULL,`full_name` VARCHAR(150) NOT NULL,`father_name` VARCHAR(150) NULL,`mother_name` VARCHAR(150) NULL,`gender` ENUM('Male','Female','Other') NULL,`dob` DATE NULL,`mobile` VARCHAR(20) NULL,`email` VARCHAR(150) NULL,`school_name` VARCHAR(255) NULL,`school_id` INT NULL,`district` VARCHAR(100) NULL,`state` VARCHAR(100) NULL,`class` INT NOT NULL,`section` CHAR(1) NOT NULL,`shift_id` INT NULL,`room_id` INT NULL,`seat_id` INT NULL,`photo` VARCHAR(255) NULL,`identity_document` VARCHAR(255) NULL,`status` ENUM('Pending','Approved','Rejected') NOT NULL,`roll_no` VARCHAR(20) NULL,`roll_number` INT NULL,`admit_generated` TINYINT(1) NOT NULL DEFAULT 0,`omr_generated` TINYINT(1) NOT NULL DEFAULT 0,`created_at` TIMESTAMP NULL,`room_no` INT NULL,`seat_no` INT NULL,`pincode` VARCHAR(10) NULL,`address` TEXT NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_app_registration` (`application_year`,`registration_no`),KEY `idx_records_app_school` (`application_year`,`school_id`),KEY `idx_records_app_shift` (`application_year`,`shift_id`),KEY `idx_records_app_room` (`application_year`,`room_id`),KEY `idx_records_app_seat` (`application_year`,`seat_id`),KEY `idx_records_app_search` (`application_year`,`full_name`,`registration_no`),CONSTRAINT `fk_records_apps_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`),CONSTRAINT `fk_records_apps_school` FOREIGN KEY (`application_year`,`school_id`) REFERENCES `records_schools` (`application_year`,`id`),CONSTRAINT `fk_records_apps_shift` FOREIGN KEY (`application_year`,`shift_id`) REFERENCES `records_seat_plan_shifts` (`application_year`,`id`),CONSTRAINT `fk_records_apps_room` FOREIGN KEY (`application_year`,`room_id`) REFERENCES `records_seat_plan_rooms` (`application_year`,`id`),CONSTRAINT `fk_records_apps_seat` FOREIGN KEY (`application_year`,`seat_id`) REFERENCES `records_seat_plan_seats` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_school_centre_assignments` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`school_id` INT NOT NULL,`centre_id` INT NOT NULL,`status` VARCHAR(50) NULL,`assigned_by` INT NULL,`approved_by` INT NULL,`approved_at` DATETIME NULL,`remarks` TEXT NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_school_centre_year` (`application_year`,`school_id`),CONSTRAINT `fk_records_sca_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`),CONSTRAINT `fk_records_sca_school` FOREIGN KEY (`application_year`,`school_id`) REFERENCES `records_schools` (`application_year`,`id`),CONSTRAINT `fk_records_sca_centre` FOREIGN KEY (`application_year`,`centre_id`) REFERENCES `records_centres` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_exam_attendance` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`qr_token` VARCHAR(255) NOT NULL,`attendance_status` ENUM('NOT_SCANNED','ABSENT','PRESENT') NOT NULL,`scanned_at` DATETIME NULL,`scanned_by_user_id` INT NULL,`scanned_by_username` VARCHAR(255) NULL,`scanned_by_role` VARCHAR(100) NULL,`created_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_attendance_app` (`application_year`,`application_id`),UNIQUE KEY `uq_records_attendance_qr` (`qr_token`),CONSTRAINT `fk_records_attendance_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_exam_attendance_qr_history` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`qr_token` VARCHAR(255) NOT NULL,`created_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_att_qr_history_token` (`qr_token`),CONSTRAINT `fk_records_att_qr_history_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_mark_components` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`name` VARCHAR(255) NOT NULL,`maximum_marks` DECIMAL(10,2) NOT NULL,`enabled` TINYINT(1) NOT NULL DEFAULT 1,`grade_counting` TINYINT(1) NOT NULL DEFAULT 1,`ranking_enabled` TINYINT(1) NOT NULL DEFAULT 1,`display_order` INT NOT NULL DEFAULT 0,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),CONSTRAINT `fk_records_mark_components_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`),CONSTRAINT `chk_records_mark_max` CHECK (`maximum_marks` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_results` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`marks` DECIMAL(10,2) NULL,`total_marks` DECIMAL(10,2) NULL,`total_full_marks` DECIMAL(10,2) NULL,`percentage` DECIMAL(10,2) NULL,`grade` VARCHAR(50) NULL,`rank_no` INT NULL,`result_status` ENUM('Pass','Fail','Absent') NOT NULL,`created_at` TIMESTAMP NULL,`section_rank` INT NULL,`overall_rank` INT NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_result_app` (`application_year`,`application_id`),CONSTRAINT `fk_records_results_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_result_component_marks` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`result_id` INT NOT NULL,`component_id` INT NOT NULL,`marks` DECIMAL(10,2) NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_result_component` (`application_year`,`result_id`,`component_id`),CONSTRAINT `fk_records_rcm_result` FOREIGN KEY (`application_year`,`result_id`) REFERENCES `records_results` (`application_year`,`id`),CONSTRAINT `fk_records_rcm_component` FOREIGN KEY (`application_year`,`component_id`) REFERENCES `records_mark_components` (`application_year`,`id`),CONSTRAINT `chk_records_rcm_marks` CHECK (`marks` >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_result_qr` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`qr_token` VARCHAR(255) NOT NULL,`created_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_result_qr_app` (`application_year`,`application_id`),UNIQUE KEY `uq_records_result_qr_token` (`qr_token`),CONSTRAINT `fk_records_result_qr_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_certificates` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`certificate_no` VARCHAR(30) NULL,`certificate_type` ENUM('Participation','Merit','Gold','Silver','Bronze','Appreciation') NOT NULL,`issue_date` DATE NULL,`qr_code` VARCHAR(255) NULL,`created_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_certificate_no` (`application_year`,`certificate_no`),CONSTRAINT `fk_records_cert_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_certificate_settings` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`exam_name` VARCHAR(255) NULL,`organized_by` VARCHAR(255) NULL,`organized_by_label` VARCHAR(255) NULL,`left_signature` VARCHAR(255) NULL,`left_signature_label` VARCHAR(255) NULL,`right_signature` VARCHAR(255) NULL,`right_signature_label` VARCHAR(255) NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_certificate_settings_year` (`application_year`),CONSTRAINT `fk_records_certificate_settings_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_certificate_category_settings` (`application_year` YEAR NOT NULL,`id` INT UNSIGNED NOT NULL,`category_key` VARCHAR(20) NOT NULL,`certificate_name` VARCHAR(255) NOT NULL,`certificate_description` TEXT NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_certificate_category_year_key` (`application_year`,`category_key`),CONSTRAINT `fk_records_certificate_category_year` FOREIGN KEY (`application_year`) REFERENCES `records_archive_years` (`application_year`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_counted_omr` (`application_year` YEAR NOT NULL,`id` INT NOT NULL,`application_id` INT NOT NULL,`file_name` VARCHAR(255) NULL,`original_name` VARCHAR(255) NULL,`mime_type` VARCHAR(100) NULL,`file_size` BIGINT NULL,`created_at` TIMESTAMP NULL,`updated_at` TIMESTAMP NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_omr_app` (`application_year`,`application_id`),CONSTRAINT `fk_records_omr_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_login_information_pdfs` (`application_year` YEAR NOT NULL,`id` BIGINT UNSIGNED NOT NULL,`application_id` INT NOT NULL,`file_name` VARCHAR(255) NULL,`file_path` VARCHAR(500) NULL,`prepared_at` DATETIME NULL,PRIMARY KEY (`application_year`,`id`),UNIQUE KEY `uq_records_login_pdf_app` (`application_year`,`application_id`),CONSTRAINT `fk_records_login_pdf_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `records_admit_downloads` (`application_year` YEAR NOT NULL,`id` BIGINT UNSIGNED NOT NULL,`application_id` INT NOT NULL,`registration_no` VARCHAR(100) NULL,`student_name` VARCHAR(255) NULL,`google_subject` VARCHAR(255) NULL,`google_email` VARCHAR(320) NULL,`google_name` VARCHAR(255) NULL,`downloader_name` VARCHAR(255) NULL,`mobile` VARCHAR(20) NULL,`mobile_verified` TINYINT(1) NULL,`otp_provider` VARCHAR(50) NULL,`otp_request_id` VARCHAR(255) NULL,`verified_at` DATETIME NULL,`downloaded_at` DATETIME NULL,`ip_address` VARCHAR(45) NULL,`user_agent` TEXT NULL,PRIMARY KEY (`application_year`,`id`),KEY `idx_records_admit_downloads_app` (`application_year`,`application_id`),CONSTRAINT `fk_records_admit_downloads_app` FOREIGN KEY (`application_year`,`application_id`) REFERENCES `records_applications` (`application_year`,`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
